func MediumConfig() *ConfigObj {
	obj, err := parsePrimaryBytes(cMediumPrimaryBytes(), false)
	if err != nil {
		panic(err)
	}
	return obj
}

func MediumYAML() []byte { return append([]byte(nil), cMediumYAMLBytes...) }

func MediumJSON() []byte { return append([]byte(nil), cMediumJSONBytes...) }

func MediumHJSON() []byte { return append([]byte(nil), cMediumHJSONBytes...) }

func HasMedium() bool { return true }

func cMediumPrimaryBytes() []byte {
	return cMediumYAMLBytes
}

func PresetNames() []string {
	nameTextArr := make([]string, 0, len(cPresetConfigByNameMap))
	for nameText := range cPresetConfigByNameMap {
		nameTextArr = append(nameTextArr, nameText)
	}
	sort.Strings(nameTextArr)
	return nameTextArr
}

func Preset(nameText string) (*ConfigObj, bool) {
	ctorObj := cPresetConfigByNameMap[nameText]
	if ctorObj == nil {
		return nil, false
	}
	return ctorObj(), true
}

func PresetYAML(nameText string) ([]byte, bool) {
	dataArr, existsFlag := cPresetYAMLByNameMap[nameText]
	if !existsFlag {
		return nil, false
	}
	return append([]byte(nil), dataArr...), true
}

func PresetJSON(nameText string) ([]byte, bool) {
	dataArr, existsFlag := cPresetJSONByNameMap[nameText]
	if !existsFlag {
		return nil, false
	}
	return append([]byte(nil), dataArr...), true
}

func PresetHJSON(nameText string) ([]byte, bool) {
	dataArr, existsFlag := cPresetHJSONByNameMap[nameText]
	if !existsFlag {
		return nil, false
	}
	return append([]byte(nil), dataArr...), true
}

var cPresetConfigByNameMap = map[string]func() *ConfigObj{
	"full":    FullConfig,
	"minimal": MinimalConfig,
	"medium":  MediumConfig,
}

var cPresetYAMLByNameMap = map[string][]byte{
	"full":    cFullYAMLBytes,
	"minimal": cMinimalYAMLBytes,
	"medium":  cMediumYAMLBytes,
}

var cPresetJSONByNameMap = map[string][]byte{
	"full":    cFullJSONBytes,
	"minimal": cMinimalJSONBytes,
	"medium":  cMediumJSONBytes,
}

var cPresetHJSONByNameMap = map[string][]byte{
	"full":    cFullHJSONBytes,
	"minimal": cMinimalHJSONBytes,
	"medium":  cMediumHJSONBytes,
}
